const ALL_VIEWPORTS: ViewportInfo[] = [
  // Each profile pins an explicit width×height AND the Playwright project name that emulates it
  { project: 'desktop',       label: 'Desktop Chrome',  width: 1920, height: 1080, type: 'desktop' },
  { project: 'mobile-chrome', label: 'Pixel 7',         width: 412,  height: 915,  type: 'portrait' },
  { project: 'mobile-safari', label: 'iPhone 15 Pro Max', width: 430, height: 932, type: 'portrait' },
  // ...6 more upright/sideways phone profiles
];

function getViewports(includeLandscape: boolean): ViewportInfo[] {
  if (includeLandscape) return ALL_VIEWPORTS;
  // Quick run: drop the sideways profiles, keeping desktop + upright phones (the common-case coverage)
  return ALL_VIEWPORTS.filter(v => v.type !== 'landscape');
}

function runCaptures(input: ResponsiveInput, viewports: ViewportInfo[]): void {
  const configPath = path.join(browserDir, 'responsive.config.ts');
  // One --project flag per selected viewport; the config maps each project name to its device + engine
  const projectArgs = viewports.map(v => `--project=${v.project}`).join(' ');
  // --grep targets only the tagged capture spec so unrelated tests in the suite don't run
  const args = ['npx', 'playwright', 'test', `--config=${configPath}`,
                '--grep', '@design-capture', projectArgs];
  if (input.headed) args.push('--headed');

  try {
    // stdio:inherit streams Playwright's live progress to the console; 600s ceiling for the full sweep
    execSync(args.join(' '), { cwd: browserDir, stdio: 'inherit', timeout: 600000 });
  } catch (error: any) {
    // Non-zero exit is expected if some captures fail — handled below
    log(`Capture completed with exit code ${error.status || 1}`, 'warn');
  }
}

function buildReport(viewports: ViewportInfo[], screenFilter: string[]): ResponsiveReport {
  const screens = screenFilter.map(screenId => {
    const captures = viewports.map(vp => {
      // VIEWPORT_LABEL_MAP turns the project name into the filename slug the capture spec wrote
      const filename = `${screenId}-${VIEWPORT_LABEL_MAP[vp.project]}.png`;
      // Existence on disk IS the pass signal — a missing file means the screen failed to render there
      const exists = fs.existsSync(path.join(capturesDir, filename));
      return { screenId, viewport: vp.label, path: filename, exists };
    });
    return { id: screenId, captures,
             // Per-screen coverage: how many of its viewports produced a file
             capturedViewports: captures.filter(c => c.exists).length,
             totalViewports: viewports.length };
  });

  return { timestamp: new Date().toISOString(), viewports, screens,
           totalScreens: screenFilter.length,
           // Denominator and numerator for the headline coverage percentage
           totalCaptures: screens.length * viewports.length,
           capturedCount: screens.reduce((n, s) => n + s.capturedViewports, 0) };
}

function generateMarkdown(report: ResponsiveReport): string {
  const lines: string[] = [];
  // Header row: first token of each viewport label (e.g. "Pixel", "iPhone") keeps columns narrow
  const vpHeaders = report.viewports.map(v => v.label.split(' ')[0]).join(' | ');
  lines.push(`| Screen | ${vpHeaders} |`);

  for (const screen of report.screens) {
    // Y where the capture exists, - where it's missing — one cell per viewport, same order as the header
    const cells = screen.captures.map(c => c.exists ? 'Y' : '-');
    lines.push(`| ${screen.id} | ${cells.join(' | ')} |`);
  }

  // Second section names only the incomplete screens so gaps are actionable, not buried in the grid
  const missing = report.screens.filter(s => s.capturedViewports < s.totalViewports);
  if (missing.length > 0) {
    lines.push('## Missing Captures');
    for (const s of missing) {
      // List the specific viewports that failed for this screen, by human label
      const gaps = s.captures.filter(c => !c.exists).map(c => c.viewport);
      lines.push(`- **${s.id}**: ${gaps.join(', ')}`);
    }
  }
  return lines.join('\n');
}

async function writeReports(report: ResponsiveReport, generateWord: boolean) {
  // Colons/dots stripped and truncated to yyyy-mm-ddThh-mm-ss — filesystem-safe, sortable, unique per run
  const ts = new Date().toISOString().replace(/[:.]/g, '-').slice(0, 19);

  const jsonPath = path.join(reportsDir, `responsive-report-${ts}.json`);
  // 2-space pretty-print so the JSON stays diff-friendly and human-readable
  fs.writeFileSync(jsonPath, JSON.stringify(report, null, 2));

  const mdPath = path.join(reportsDir, `responsive-report-${ts}.md`);
  fs.writeFileSync(mdPath, generateMarkdown(report));

  const paths = { json: jsonPath, markdown: mdPath };
  if (generateWord) {
    const wordPath = path.join(reportsDir, `responsive-report-${ts}.docx`);
    await generateWordDoc(report, wordPath); // embeds the actual PNGs
    paths.word = wordPath;
  }
  return paths;
}
